@import url('https://fonts.googleapis.com/css2?family=Open+Sans:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* Frutiger Aero — 2000s: sky blue + vivid green, glossy bubbles, lens flares */
.theme-frutiger-aero {
  --bg: oklch(0.88 0.07 220);
  --surface: oklch(0.99 0.01 220 / 80%);
  --surface-2: oklch(0.93 0.05 205 / 85%);
  --fg: oklch(0.26 0.05 245);
  --fg-muted: oklch(0.46 0.05 235);
  --accent: oklch(0.632 0.190 145.0);
  --accent-fg: oklch(0.99 0 0);
  --accent-2: oklch(0.66 0.16 240);
  --line: oklch(1 0 0 / 75%);
  --success: oklch(0.72 0.19 145);
  --warning: oklch(0.84 0.16 88);
  --danger: oklch(0.62 0.2 25);

  --radius: 1rem;
  --radius-sm: 0.625rem;
  --radius-lg: 1.75rem;
  --radius-pill: 9999px;

  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 95%), 0 2px 5px -1px oklch(0.35 0.08 240 / 35%);
  --shadow-2: inset 0 2px 0 oklch(1 0 0 / 95%), inset 0 -8px 16px oklch(0.6 0.1 220 / 18%),
    0 12px 26px -10px oklch(0.35 0.08 240 / 45%);
  --shadow-3: inset 0 3px 0 oklch(1 0 0 / 95%), 0 26px 54px -18px oklch(0.32 0.09 240 / 50%);
  --glow: 0 0 26px -4px oklch(0.72 0.19 145 / 75%);

  --border-width: 1px;
  --blur-amount: 10px;

  --font-display: "Open Sans", "Segoe UI", sans-serif;
  --font-body: "Open Sans", "Segoe UI", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;

  --tracking-display: -0.01em;
  --label-transform: none;
  --label-tracking: 0.03em;

  background-color: var(--bg);
  background-image:
    radial-gradient(circle at 18% 22%, oklch(1 0 0 / 55%) 0 3rem, transparent 3.2rem),
    radial-gradient(circle at 76% 14%, oklch(1 0 0 / 40%) 0 1.6rem, transparent 1.8rem),
    radial-gradient(circle at 62% 74%, oklch(0.9 0.14 145 / 45%) 0 5rem, transparent 5.4rem),
    radial-gradient(40rem 24rem at 92% -8%, oklch(0.99 0.06 95 / 80%), transparent 62%),
    linear-gradient(180deg, oklch(0.86 0.11 230) 0%, oklch(0.93 0.06 200) 55%, oklch(0.9 0.13 145) 100%);
  background-attachment: fixed;
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-frutiger-aero h1,
.theme-frutiger-aero h2,
.theme-frutiger-aero h3 {
  font-family: var(--font-display);
  font-weight: 700;
  letter-spacing: var(--tracking-display);
  text-shadow: 0 1px 0 oklch(1 0 0 / 70%);
}

/* signature */
.theme-frutiger-aero h1 { background: linear-gradient(180deg, oklch(0.45 0.16 245), oklch(0.52 0.17 150)); -webkit-background-clip: text; background-clip: text; color: transparent; text-shadow: none; }
.theme-frutiger-aero button { background-image: linear-gradient(180deg, oklch(1 0 0 / 55%), transparent 50%, oklch(0 0 0 / 10%)); box-shadow: inset 0 1px 0 oklch(1 0 0 / 80%), 0 2px 8px oklch(0.5 0.1 220 / 30%); }

/* depth */
.theme-frutiger-aero thead th { background-image: linear-gradient(180deg, oklch(1 0 0 / 90%), oklch(0.88 0.06 210 / 80%)); border-bottom: 1px solid oklch(0.66 0.16 240 / 40%); color: oklch(0.34 0.06 240); font-size: 0.74em; font-weight: 700; letter-spacing: 0.04em; text-shadow: 0 1px 0 oklch(1 0 0 / 85%); }
.theme-frutiger-aero td { border-bottom: 1px solid oklch(0.66 0.16 240 / 18%); }
.theme-frutiger-aero tbody tr:hover { background: linear-gradient(180deg, oklch(0.95 0.05 200 / 70%), oklch(0.92 0.09 150 / 40%)); }
.theme-frutiger-aero input, .theme-frutiger-aero textarea, .theme-frutiger-aero select { background: linear-gradient(180deg, oklch(0.93 0.02 210), oklch(1 0 0) 40%); border: 1px solid oklch(0.66 0.16 240 / 45%); border-radius: var(--radius-sm); box-shadow: inset 0 2px 3px oklch(0.5 0.08 230 / 20%); }
.theme-frutiger-aero input:focus-visible, .theme-frutiger-aero textarea:focus-visible, .theme-frutiger-aero select:focus-visible { outline: none; border-color: var(--accent); box-shadow: inset 0 2px 3px oklch(0.5 0.08 230 / 15%), 0 0 10px oklch(0.72 0.19 145 / 60%); }
.theme-frutiger-aero kbd { background: linear-gradient(180deg, oklch(1 0 0 / 95%), oklch(0.88 0.05 210 / 90%)); border: 1px solid oklch(0.66 0.16 240 / 45%); border-radius: 0.5em; padding: 0.1em 0.45em; font-family: var(--font-mono); font-size: 0.85em; box-shadow: inset 0 1px 0 oklch(1 0 0), 0 1px 3px oklch(0.5 0.08 230 / 30%); }
.theme-frutiger-aero a { color: oklch(0.5 0.16 240); font-weight: 600; text-decoration: underline; text-decoration-color: oklch(0.72 0.19 145 / 70%); text-decoration-thickness: 2px; text-underline-offset: 0.18em; }
.theme-frutiger-aero a:hover { color: oklch(0.55 0.18 150); text-shadow: 0 0 10px oklch(0.72 0.19 145 / 50%); }
.theme-frutiger-aero ::selection { background: oklch(0.72 0.19 145 / 35%); }
.theme-frutiger-aero ::-webkit-scrollbar { width: 13px; height: 13px; }
.theme-frutiger-aero ::-webkit-scrollbar-track { background: oklch(0.93 0.03 210 / 80%); border-radius: 9999px; }
.theme-frutiger-aero ::-webkit-scrollbar-thumb { background: linear-gradient(90deg, oklch(0.82 0.15 150), oklch(0.66 0.17 150)); border-radius: 9999px; border: 2px solid oklch(1 0 0 / 70%); box-shadow: inset 0 1px 0 oklch(1 0 0 / 80%); }
.theme-frutiger-aero ::-webkit-scrollbar-thumb:hover { background: linear-gradient(90deg, oklch(0.85 0.16 150), oklch(0.7 0.18 150)); }
.theme-frutiger-aero .label-caps { color: oklch(0.5 0.16 240); text-shadow: 0 1px 0 oklch(1 0 0 / 80%); }
.theme-frutiger-aero .themed-border { border-color: oklch(1 0 0 / 80%); box-shadow: 0 0 0 1px oklch(0.66 0.16 240 / 22%); }
.theme-frutiger-aero button:hover { background-image: linear-gradient(180deg, oklch(1 0 0 / 70%), transparent 50%, oklch(0 0 0 / 8%)); box-shadow: inset 0 1px 0 oklch(1 0 0 / 90%), var(--glow); }
.theme-frutiger-aero button:active { background-image: linear-gradient(180deg, oklch(0 0 0 / 10%), transparent 50%, oklch(1 0 0 / 30%)); }

/* alt mode: midnight aqua — deep-sea Vista, bioluminescent green on ocean blue */
.theme-frutiger-aero.alt-mode {
  --bg: oklch(0.24 0.06 240);
  --surface: oklch(0.3 0.06 235 / 85%);
  --surface-2: oklch(0.35 0.07 230 / 88%);
  --fg: oklch(0.95 0.02 210);
  --fg-muted: oklch(0.76 0.04 220);
  --line: oklch(0.72 0.19 145 / 35%);
  --shadow-1: inset 0 1px 0 oklch(1 0 0 / 25%), 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: inset 0 2px 0 oklch(1 0 0 / 22%), 0 12px 26px -10px oklch(0 0 0 / 55%);
  --shadow-3: inset 0 3px 0 oklch(1 0 0 / 20%), 0 26px 54px -18px oklch(0 0 0 / 65%);
  background-image:
    radial-gradient(circle at 18% 22%, oklch(1 0 0 / 12%) 0 3rem, transparent 3.2rem),
    radial-gradient(circle at 76% 14%, oklch(1 0 0 / 9%) 0 1.6rem, transparent 1.8rem),
    radial-gradient(circle at 62% 74%, oklch(0.6 0.15 150 / 30%) 0 5rem, transparent 5.4rem),
    linear-gradient(180deg, oklch(0.3 0.08 235) 0%, oklch(0.22 0.06 240) 55%, oklch(0.28 0.09 160) 100%);
}
.theme-frutiger-aero.alt-mode h1 { background: linear-gradient(180deg, oklch(0.85 0.1 210), oklch(0.85 0.17 150)); -webkit-background-clip: text; background-clip: text; color: transparent; }
.theme-frutiger-aero.alt-mode h1, .theme-frutiger-aero.alt-mode h2, .theme-frutiger-aero.alt-mode h3 { text-shadow: none; }
.theme-frutiger-aero.alt-mode thead th { background-image: linear-gradient(180deg, oklch(0.4 0.07 230 / 90%), oklch(0.32 0.06 235 / 85%)); color: oklch(0.88 0.05 200); text-shadow: none; }
.theme-frutiger-aero.alt-mode td { border-bottom-color: oklch(0.72 0.19 145 / 20%); }
.theme-frutiger-aero.alt-mode tbody tr:hover { background: linear-gradient(180deg, oklch(0.36 0.07 220 / 70%), oklch(0.34 0.1 160 / 40%)); }
.theme-frutiger-aero.alt-mode input, .theme-frutiger-aero.alt-mode textarea, .theme-frutiger-aero.alt-mode select { background: linear-gradient(180deg, oklch(0.2 0.05 240), oklch(0.28 0.06 235) 40%); border-color: oklch(0.72 0.19 145 / 35%); color: var(--fg); box-shadow: inset 0 2px 3px oklch(0 0 0 / 35%); }
.theme-frutiger-aero.alt-mode kbd { background: linear-gradient(180deg, oklch(0.4 0.06 230 / 95%), oklch(0.3 0.06 235 / 90%)); border-color: oklch(0.72 0.19 145 / 35%); box-shadow: inset 0 1px 0 oklch(1 0 0 / 20%), 0 1px 3px oklch(0 0 0 / 45%); }
.theme-frutiger-aero.alt-mode a { color: oklch(0.8 0.16 150); }
.theme-frutiger-aero.alt-mode a:hover { color: oklch(0.85 0.17 150); }
.theme-frutiger-aero.alt-mode .label-caps { color: oklch(0.8 0.16 150); text-shadow: none; }
.theme-frutiger-aero.alt-mode ::-webkit-scrollbar-track { background: oklch(0.26 0.05 238 / 80%); }
.theme-frutiger-aero.alt-mode ::-webkit-scrollbar-thumb { border-color: oklch(0.35 0.06 230 / 70%); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
